code.cpp:
class Solution {
public:
    vector<int> sortEvenOdd(vector<int>& nums) {
        int countEven[101] = {0};
        int countOdd[101] = {0};
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) countEven[nums[i]]++;
            else countOdd[nums[i]]++;
        }
        int evenIdx = 0;
        for (int v = 1; v <= 100; v++) {
            while (countEven[v] > 0) {
                nums[evenIdx] = v;
                evenIdx += 2;
                countEven[v]--;
            }
        }
        int oddIdx = 1;
        for (int v = 100; v >= 1; v--) {
            while (countOdd[v] > 0) {
                nums[oddIdx] = v;
                oddIdx += 2;
                countOdd[v]--;
            }
        }
        return nums;
    }
};
